CREATE TABLE IF NOT EXISTS settings (k VARCHAR(100) NOT NULL PRIMARY KEY, v LONGTEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT '', password_hash VARCHAR(255) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, last_login DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS login_attempts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(45) NOT NULL, username VARCHAR(60) NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY ip_time (ip, created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS slides (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(10) NOT NULL DEFAULT 'image', media VARCHAR(255) NOT NULL DEFAULT '', poster VARCHAR(255) NOT NULL DEFAULT '', kicker VARCHAR(190) NOT NULL DEFAULT '', title VARCHAR(255) NOT NULL DEFAULT '', body TEXT, btn1_text VARCHAR(120) NOT NULL DEFAULT '', btn1_url VARCHAR(255) NOT NULL DEFAULT '', btn2_text VARCHAR(120) NOT NULL DEFAULT '', btn2_url VARCHAR(255) NOT NULL DEFAULT '', overlay TINYINT UNSIGNED NOT NULL DEFAULT 45, align VARCHAR(10) NOT NULL DEFAULT 'left', sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sections (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, skey VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL DEFAULT '', kicker VARCHAR(190) NOT NULL DEFAULT '', title VARCHAR(255) NOT NULL DEFAULT '', body TEXT, image VARCHAR(255) NOT NULL DEFAULT '', btn_text VARCHAR(120) NOT NULL DEFAULT '', btn_url VARCHAR(255) NOT NULL DEFAULT '', style VARCHAR(20) NOT NULL DEFAULT 'light', layout VARCHAR(20) NOT NULL DEFAULT '', lim INT NOT NULL DEFAULT 0, sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS regions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, title VARCHAR(190) NOT NULL, summary TEXT, content LONGTEXT, image VARCHAR(255) NOT NULL DEFAULT '', cover VARCHAR(255) NOT NULL DEFAULT '', meta_title VARCHAR(255) NOT NULL DEFAULT '', meta_desc VARCHAR(400) NOT NULL DEFAULT '', sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS hotels (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(190) NOT NULL, region_id INT UNSIGNED NULL, location VARCHAR(255) NOT NULL DEFAULT '', concept VARCHAR(190) NOT NULL DEFAULT '', stars TINYINT UNSIGNED NOT NULL DEFAULT 5, summary TEXT, description LONGTEXT, features TEXT, image VARCHAR(255) NOT NULL DEFAULT '', factsheet VARCHAR(255) NOT NULL DEFAULT '', website VARCHAR(255) NOT NULL DEFAULT '', featured TINYINT(1) NOT NULL DEFAULT 1, meta_title VARCHAR(255) NOT NULL DEFAULT '', meta_desc VARCHAR(400) NOT NULL DEFAULT '', sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, KEY region_id (region_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS hotel_images (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, hotel_id INT UNSIGNED NOT NULL, image VARCHAR(255) NOT NULL, sort INT NOT NULL DEFAULT 0, KEY hotel_id (hotel_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, title VARCHAR(190) NOT NULL, kicker VARCHAR(190) NOT NULL DEFAULT '', summary TEXT, content LONGTEXT, image VARCHAR(255) NOT NULL DEFAULT '', icon VARCHAR(40) NOT NULL DEFAULT 'star', meta_title VARCHAR(255) NOT NULL DEFAULT '', meta_desc VARCHAR(400) NOT NULL DEFAULT '', sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, title VARCHAR(190) NOT NULL, subtitle VARCHAR(255) NOT NULL DEFAULT '', content LONGTEXT, image VARCHAR(255) NOT NULL DEFAULT '', cover VARCHAR(255) NOT NULL DEFAULT '', meta_title VARCHAR(255) NOT NULL DEFAULT '', meta_desc VARCHAR(400) NOT NULL DEFAULT '', sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS factsheets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, title VARCHAR(190) NOT NULL, file VARCHAR(255) NOT NULL DEFAULT '', hotel_id INT UNSIGNED NULL, image VARCHAR(255) NOT NULL DEFAULT '', sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, grp VARCHAR(30) NOT NULL, title VARCHAR(190) NOT NULL DEFAULT '', body TEXT, val VARCHAR(60) NOT NULL DEFAULT '', icon VARCHAR(40) NOT NULL DEFAULT '', sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, KEY grp (grp)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS menu_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, menu VARCHAR(20) NOT NULL DEFAULT 'header', parent_id INT UNSIGNED NULL, title VARCHAR(190) NOT NULL, url VARCHAR(255) NOT NULL DEFAULT '', new_tab TINYINT(1) NOT NULL DEFAULT 0, sort INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, KEY menu (menu, parent_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(20) NOT NULL DEFAULT 'iletisim', name VARCHAR(120) NOT NULL DEFAULT '', surname VARCHAR(120) NOT NULL DEFAULT '', company VARCHAR(190) NOT NULL DEFAULT '', country VARCHAR(120) NOT NULL DEFAULT '', phone VARCHAR(60) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT '', subject VARCHAR(255) NOT NULL DEFAULT '', hotel VARCHAR(190) NOT NULL DEFAULT '', message TEXT, ip VARCHAR(45) NOT NULL DEFAULT '', is_read TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY created_at (created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
